"""Tests for the command line: the reproduce command the generated files carry."""

from __future__ import annotations

import argparse
from pathlib import Path

import pytest

from tools.convert import bzl, cli


def parse(*argv: str) -> argparse.Namespace:
    return cli.build_parser().parse_args(["convert", *argv])


# The reproduce command.


def test_flags_as_given() -> None:
    """Every flag that differs from its default, in the help's order; defaults and the flags
    that do not shape the output are left out."""
    args = parse(
        "--src",
        "https://x/foo-1.2.tar.gz",
        "--out",
        "out",
        "--external",
        "--dev",
        "--annotate",
        "--m4-dir",
        "m4",
        "--keep-work",
        "--buildifier",
        "/usr/bin/buildifier",
        "--decisions",
        "d.bzl",
        "--layout",
        "package",
    )
    assert cli.reproduce_command(args) == (
        "bazel run //tools/convert -- convert --src https://x/foo-1.2.tar.gz --m4-dir m4 --out out "
        "--layout package --external --annotate --decisions d.bzl --dev"
    )
    assert cli.reproduce_command(parse("--src", "s", "--out", "o", "--in-repo")) == (
        "bazel run //tools/convert -- convert --src s --out o --in-repo"
    )


def test_entry_supplies_its_own() -> None:
    args = parse(
        "--bcr-entry",
        "bcr/modules/foo/1.2",
        "--src",
        "https://x/foo.tar.gz",
        "--integrity",
        "sha256-abc",
        "--external",
        "--dev",
        "--out",
        "/tmp/scratch",
    )
    assert cli.reproduce_command(args) == (
        "bazel run //tools/convert -- convert --bcr-entry bcr/modules/foo/1.2 --external --dev"
    )


def test_paths_relative_to_the_invocation_directory(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    root = tmp_path.resolve()
    (root / "src").mkdir()
    monkeypatch.setenv("BUILD_WORKING_DIRECTORY", str(root))
    args = parse(
        "--src",
        str(root / "src"),
        "--out",
        str(root / "out"),
        "--decisions",
        str(root / "out/decisions.bzl"),
        "--m4-dir",
        str(Path.home() / "work/m4"),
    )
    assert cli.reproduce_command(args) == (
        "bazel run //tools/convert -- convert --src src --m4-dir ~/work/m4 --out out --decisions out/decisions.bzl"
    )


# The hand-written BUILD files of the generated packages.


OURS = "# @generated by rules_cc_autoconf convert\n"


def test_hand_builds_and_packages(tmp_path: Path) -> None:
    """Before a conversion: the root's hand-written BUILD.bazel and those of the packages an
    earlier run generated into are read (a generated BUILD.bazel of the layout before
    autoconf.bzl is not hand-written; its BUILD.additions.bazel is); a hand-written package
    elsewhere is a package boundary, not a text to read."""
    root = tmp_path
    (root / "BUILD.bazel").write_text('load(":autoconf.bzl", "autoconf_targets")\n\nautoconf_targets()\n')
    (root / "autoconf.bzl").write_text(OURS)
    (root / "extension").mkdir()
    (root / "extension/BUILD.bazel").write_text(OURS + "old = 1\n")
    (root / "extension/BUILD.additions.bazel").write_text('cc_library(name = "ext")\n')
    (root / "tests").mkdir()
    (root / "tests/BUILD.bazel").write_text('cc_test(name = "t")\n')
    hand = cli._hand_builds(root)
    assert sorted(hand) == ["", "extension"]
    assert hand[""] == cli.HandBuild('load(":autoconf.bzl", "autoconf_targets")\n\nautoconf_targets()\n', "BUILD.bazel")
    assert hand["extension"] == cli.HandBuild('cc_library(name = "ext")\n', "BUILD.additions.bazel")
    assert cli._hand_packages(root) == {"extension", "tests"}
    assert cli._hand_builds(None) == {} and cli._hand_packages(None) == set()


def test_place_hand_builds(tmp_path: Path) -> None:
    """After the generated files are placed: a package without a BUILD.bazel gets the stub; one
    with a BUILD.additions.bazel of the earlier layout gets it moved in (a generated BUILD.bazel
    in the way goes), with the top-level constants it reads loaded and the inner ones reported;
    a BUILD.bazel that does not call the macro is reported."""
    root = tmp_path
    bzl_text = (
        '"""x"""\n\nload("@rules_cc//cc:cc_library.bzl", "cc_library")\n\nvisibility("private")\n\n'
        'NO_WARNINGS = ["-w"]\n\ndef autoconf_targets():\n'
        '    SRC_HDRS = native.glob(["*.h"])\n    native.filegroup(name = "h", srcs = SRC_HDRS)\n'
    )
    for package in ("", "extension", "other"):
        (root / package).mkdir(exist_ok=True)
        (root / package / "autoconf.bzl").write_text(bzl_text)
    (root / "extension/BUILD.bazel").write_text(OURS + "old = 1\n")
    (root / "extension/BUILD.additions.bazel").write_text(
        'cc_library(\n    name = "ext",\n    srcs = SRC_HDRS,\n    copts = NO_WARNINGS,\n)\n'
    )
    (root / "other/BUILD.bazel").write_text('cc_library(name = "mine")\n')
    report: list[str] = []
    written = cli._place_hand_builds(root, ["", "extension", "other"], report, None)
    assert [p.relative_to(root).as_posix() for p in written] == ["BUILD.bazel", "extension/BUILD.bazel"]
    assert (root / "BUILD.bazel").read_text() == bzl.build_file()
    moved = (root / "extension/BUILD.bazel").read_text()
    assert moved.startswith(
        'load(":autoconf.bzl", "NO_WARNINGS", "autoconf_targets")\nload("@rules_cc//cc:cc_library.bzl", "cc_library")\n'
    )
    assert "old = 1" not in moved
    assert 'cc_library(\n    name = "ext",' in moved
    assert not (root / "extension/BUILD.additions.bazel").exists()
    text = "\n".join(report)
    assert "## Hand-written files moved" in text
    assert "`extension/BUILD.additions.bazel` into `extension/BUILD.bazel`; it reads SRC_HDRS" in text
    assert "## BUILD files that do not call autoconf_targets()" in text
    assert "- `other/BUILD.bazel`" in text
    assert cli._place_hand_builds(root, ["", "extension"], [], None) == []
